import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-01 — Trang chủ","description":"","frontmatter":{"title":"SC-01 — Trang chủ"},"headers":[],"relativePath":"wireframes/public/sc-01-trang-chu.md","filePath":"wireframes/public/sc-01-trang-chu.md","lastUpdated":1791606799000}'),c={name:"wireframes/public/sc-01-trang-chu.md"};function t(e,s,p,d,o,r){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-01-—-trang-chu" tabindex="-1">SC-01 — Trang chủ <a class="header-anchor" href="#sc-01-—-trang-chu" aria-label="Permalink to &quot;SC-01 — Trang chủ&quot;">​</a></h1><p><span class="wf-badge info">Route: /</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-01 · docs/03 UC-03 · docs/02 FR-HS-06 · docs/08 BR-PKG-06</span></p><p><strong>Ai xem màn này</strong>: Mọi đối tượng — Guest (đa số, đến từ SEO/quảng cáo), Thành viên, Chủ nhà. Đây là mặt tiền của sàn: phải trả lời được trong 5 giây &quot;sàn này bán cái gì, ở đâu, giá bao nhiêu, có đấu giá không&quot;. <strong>Mục đích / cảm xúc thiết kế</strong>: tin cậy — minh bạch, không &quot;màu sale lòe&quot; (docs/05 §1.1). Con số thật (giá, diện tích, giờ mở phiên) là nhân vật chính, không phải banner khuyến mãi. <strong>Ví dụ số dùng trong bản vẽ</strong>: căn <code>CT2-A18.05</code> dự án NOXH <code>HP-380</code> · <code>72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</code> · giá <code>1.250.000.000 ₫</code> · phiên đấu giá mở giá <code>1.800.000.000 ₫</code>, cọc <code>90.000.000 ₫</code>.</p><h2 id="_1-desktop-—-trang-chu-đay-đu-guest" tabindex="-1">1. Desktop — trang chủ đầy đủ (Guest) <a class="header-anchor" href="#_1-desktop-—-trang-chu-đay-đu-guest" aria-label="Permalink to &quot;1. Desktop — trang chủ đầy đủ (Guest)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng nhập</span><span class="wf-btn sm primary">Đăng bán <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">4</span></span></span></div><div class="wf-container"><div class="wf-hero"><span class="wf-title xl">Mua nhà ở xã hội — đúng giá, rõ pháp lý</span><br><span class="wf-text">Tin đăng đã xác minh sổ · giá không vượt trần dự án · đấu giá công khai, ẩn danh</span><div class="wf-row middle" style="margin-top:14px;max-width:640px;margin-left:auto;margin-right:auto;"><div class="wf-search">🔍 Từ khóa, mã căn hoặc tên dự án… <span class="wf-callout">1</span></div><span class="wf-btn primary">Tìm kiếm</span></div><div class="wf-row middle" style="justify-content:center;margin-top:10px;"><span class="wf-small wf-accent">Dự án NOXH HP-380 · Hải Phòng</span><span class="wf-small wf-accent">Căn 2 PN dưới 1,5 tỷ</span><span class="wf-small wf-accent">Phiên đấu giá sắp mở</span></div></div><div class="wf-row between middle" style="margin-top:22px;"><span class="wf-title lg">Tin mới đăng <span class="wf-callout">2</span></span><span class="wf-small wf-accent">Xem tất cả → SC-02</span></div><div class="wf-grid cols-3" style="margin-top:10px;"><div class="wf-card"><div class="wf-img" style="min-height:140px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA TIN</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-badge wf-vip">★ VIP</span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><span class="wf-money lg">1.250.000.000 ₫ <span class="wf-callout">3</span></span></div></div><div class="wf-card"><div class="wf-img" style="min-height:140px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA TIN</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span></span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn B1-07.02 — NOXH HP-380</span><span class="wf-text">65 m² · 2 PN · 1 WC · tầng 7 · Sổ hồng</span><span class="wf-money lg">1.120.000.000 ₫</span></div></div><div class="wf-card"><div class="wf-img" style="min-height:140px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA TIN</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span></span><span class="wf-badge muted">Sắp đấu giá</span></span><span class="wf-title">Căn A2-11.08 — NOXH Tràng Duệ</span><span class="wf-text">70 m² · 2 PN · 1 WC · tầng 11 · Sổ hồng</span><span class="wf-money lg">1.380.000.000 ₫</span></div></div></div><span class="wf-small">… 3 tin nữa trong lưới 6 tin (2 hàng × 3 cột trên desktop; tablet 2 cột; mobile 1 cột)</span><div class="wf-row between middle" style="margin-top:22px;"><span class="wf-title lg">Phiên đấu giá sắp mở <span class="wf-callout">5</span></span><span class="wf-small wf-accent">Tất cả phiên → SC-05</span></div><div class="wf-grid cols-3" style="margin-top:10px;"><div class="wf-card" style="border-color:var(--wf-danger);border-width:2px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge danger live">🔴 ĐANG DIỄN RA</span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><div class="wf-row between"><span class="wf-small">Giá hiện tại</span><span class="wf-money">1.926.000.000 ₫</span></div><div class="wf-center"><span class="wf-countdown sm">00:14:32</span></div><span class="wf-btn danger block">VÀO XEM LIVE → SC-06</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge info">SẮP MỞ</span><span class="wf-title">Căn A2-11.08 — NOXH Tràng Duệ</span><div class="wf-row between"><span class="wf-small">Giá khởi điểm</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-small">Mở sau</span><span class="wf-countdown sm">22:14:32</span></div><span class="wf-small">Đóng đăng ký: 11/10/2026 14:00 (GMT+7)</span><span class="wf-btn block">Xem &amp; đăng ký → SC-05</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge info">SẮP MỞ</span><span class="wf-title">Căn B3-05.01 — NOXH An Đồng</span><div class="wf-row between"><span class="wf-small">Giá khởi điểm</span><span class="wf-money">1.650.000.000 ₫</span></div><div class="wf-row between"><span class="wf-small">Mở sau</span><span class="wf-countdown sm">46:02:10</span></div><span class="wf-small">Cọc tham gia 90.000.000 ₫ · bước giá 18.000.000 ₫</span><span class="wf-btn block">Xem &amp; đăng ký → SC-05</span></div></div></div><div class="wf-card flat" style="margin-top:22px;background:var(--wf-fill);"><div class="pad wf-row middle between"><div class="wf-col" style="gap:4px;"><span class="wf-title lg">Có căn NOXH muốn bán?</span><span class="wf-text">Đăng tin miễn phí 2 căn · tin được duyệt trong 24h giờ làm việc · nâng VIP để tăng hiển thị <span class="wf-callout">4</span></span></div><span class="wf-btn primary lg">Đăng bán ngay</span></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-01 · docs/03 UC-03 · docs/08)</div><ol><li><span class="num">1</span><span><b>Search điều hướng SC-02</b>: submit → `/nha-o-xa-hoi?q={query}` (URL-sync, shareable). Gợi ý nhanh dưới ô search = các preset filter (chọn → SC-02 với query tương ứng). Không autocomplete gọi API trong v1. <span class="ref">docs/05 §3</span> <span class="ref">FR-HS-06</span></span></li><li><span class="num">2</span><span><b>6 tin mới</b> = `GET /housing?sort=newest&amp;limit=6` (chỉ tin LISTED/RESERVED). Thứ tự newest theo `listedAt desc`; nếu user có gói VIP thì badge ★ hiện trên card nhưng <b>không đổi thứ tự</b> ở khối này (featured sort chỉ áp khi user chủ động chọn ở SC-02). <span class="ref">FR-HS-06</span> <span class="ref">BR-PKG-06</span></span></li><li><span class="num">3</span><span>Tiền format chuẩn toàn site: `1.250.000.000 ₫` (chấm nghìn + dấu ₫ cách 1 space). Click card → SC-03 chi tiết tin (cùng tab). <span class="ref">docs/05 §1.1</span></span></li><li><span class="num">4</span><span><b>CTA &quot;Đăng bán&quot;</b>: Guest → SC-09/10 login kèm <b>intent deep-link return</b> về `/dang-ban` (AF-1 UC-03); User KYC ≠ APPROVED → SC-21 &quot;Đi xác minh&quot;; User KYC APPROVED → SC-22 wizard. Nút ở header và ở band cuối trang cùng hành vi. <span class="ref">BR-KYC-08</span> <span class="ref">BR-HS-01</span></span></li><li><span class="num">5</span><span><b>3 phiên sắp mở</b> = `GET /auctions?state=upcoming` (+ 1 card LIVE nếu có, xếp đầu, viền đỏ + badge pulse). Countdown đồng bộ giờ server 1 lần qua header `X-Server-Time` — không tin đồng hồ máy khách. Định dạng &quot;Mở sau&quot; = `hh:mm:ss` khi dưới 24h, thêm ngày khi xa hơn. <span class="ref">FR-AU-05</span> <span class="ref">BR-AU-21</span></span></li><li><span class="num">6</span><span>Header Guest: nút &quot;Đăng nhập&quot; → SC-09; sau khi login header đổi thành 🔔 bell (+ unread count) + avatar initials (mẫu trong SC-06). Footer link &quot;Quy chế đấu giá&quot; → SC-08#quy-che. <span class="ref">docs/05 §2</span></span></li></ol></div><h2 id="_2-mobile-360px-—-hero-xep-doc-card-1-cot" tabindex="-1">2. Mobile 360px — hero xếp dọc, card 1 cột <a class="header-anchor" href="#_2-mobile-360px-—-hero-xep-doc-card-1-cot" aria-label="Permalink to &quot;2. Mobile 360px — hero xếp dọc, card 1 cột&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm primary">Đăng bán</span></div><div class="wf-container" style="padding:12px;"><div class="wf-hero" style="padding:18px 12px;"><span class="wf-title lg">Mua nhà ở xã hội — đúng giá, rõ pháp lý</span><div class="wf-row" style="margin-top:10px;"><div class="wf-search">🔍 Mã căn, dự án…</div><span class="wf-btn primary sm">Tìm</span></div></div><div class="wf-row between middle" style="margin-top:14px;"><span class="wf-title">Tin mới đăng</span><span class="wf-small wf-accent">Tất cả →</span></div><div class="wf-card" style="margin-top:8px;"><div class="wf-img" style="min-height:120px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA TIN</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-badge wf-vip">★ VIP</span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><span class="wf-money lg">1.250.000.000 ₫</span></div></div><span class="wf-small">… cuộn dọc, mỗi card full-width (nav &quot;Mua nhà/Đấu giá/Bảng gói/Hướng dẫn&quot; chuyển thành menu ☰)</span><div class="wf-row between middle" style="margin-top:14px;"><span class="wf-title">Phiên đấu giá</span><span class="wf-small wf-accent">Tất cả →</span></div><div class="wf-card" style="margin-top:8px;border-color:var(--wf-danger);border-width:2px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-badge danger live">🔴 ĐANG DIỄN RA</span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><div class="wf-row between middle"><span class="wf-countdown sm">00:14:32</span><span class="wf-money">1.926.000.000 ₫</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — vận hành bởi An Phuc</span><span>CSKH 1900-xxx</span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Card tin và card phiên chuyển <b>1 cột full-width</b>; hero thu gọn padding, giữ nguyên ô search (hành vi điều hướng SC-02 y hệt desktop). Card LIVE luôn xếp đầu khối phiên — tap vào là tới SC-06 ngay, không qua SC-05.</span></li><li><span class="num">M</span><span>Nav desktop ẩn vào menu ☰ (drawer); nút &quot;Đăng bán&quot; giữ ở header vì là CTA chuyển đổi chính của chủ nhà. Sticky bottom bar <b>không dùng</b> ở trang chủ (chỉ SC-03/SC-06 mới có).</span></li></ol></div><h2 id="_3-loading-—-skeleton-hero-giu-nguyen-khoi-du-lieu-xam-nhap-nhay" tabindex="-1">3. Loading — skeleton (hero giữ nguyên, khối dữ liệu xám nhấp nháy) <a class="header-anchor" href="#_3-loading-—-skeleton-hero-giu-nguyen-khoi-du-lieu-xam-nhap-nhay" aria-label="Permalink to &quot;3. Loading — skeleton (hero giữ nguyên, khối dữ liệu xám nhấp nháy)&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:760px;"><span class="wf-state-label">TRẠNG THÁI: LOADING (lần đầu vào trang)</span><div class="wf-grid cols-3"><div class="wf-skeleton"><div class="wf-img" style="min-height:100px;"><span></span></div><div class="wf-lines"><span class="w-75"></span><span class="w-50"></span><span class="w-90"></span></div></div><div class="wf-skeleton"><div class="wf-img" style="min-height:100px;"><span></span></div><div class="wf-lines"><span class="w-60"></span><span class="w-40"></span><span class="w-75"></span></div></div><div class="wf-skeleton"><div class="wf-img" style="min-height:100px;"><span></span></div><div class="wf-lines"><span class="w-50"></span><span class="w-60"></span><span class="w-90"></span></div></div></div><span class="wf-small">Hero + search render ngay (tĩnh, không chờ API); skeleton chỉ ở khối &quot;Tin mới&quot; (6 ô) và &quot;Phiên sắp mở&quot; (3 ô) — 2 request độc lập, khối nào xong trước hiện trước. <span class="wf-callout">7</span></span></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">7</span><span>Skeleton dùng chung component với SC-02 (grid card). Không spinner toàn trang; không layout-shift khi data về (ô skeleton đúng kích thước card thật). <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_4-empty-error-—-hai-trang-thai-con-lai-cua-khoi-du-lieu" tabindex="-1">4. Empty + Error — hai trạng thái còn lại của khối dữ liệu <a class="header-anchor" href="#_4-empty-error-—-hai-trang-thai-con-lai-cua-khoi-du-lieu" aria-label="Permalink to &quot;4. Empty + Error — hai trạng thái còn lại của khối dữ liệu&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: EMPTY (sàn chưa có tin — giai đoạn cold start)</span><div class="wf-empty"><span class="icon">🏢</span><span class="wf-title">Chưa có tin đăng</span><br><span class="wf-text">Các dự án NOXH đã có hồ sơ — xem thông tin dự án, giá trần và loại căn trong lúc chờ tin đầu tiên.</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Xem dự án → SC-04</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: ERROR (API lỗi — hero vẫn hiện)</span><div class="wf-error-box"><span class="wf-title" style="color:var(--wf-danger);">Không tải được tin mới</span><br><span class="wf-small">Đã xảy ra lỗi khi tải dữ liệu. Vui lòng thử lại.</span><br><span class="wf-trace">traceId: 9f2c1ab4…</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn">Thử lại</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span>Empty đúng copy docs/05 §3: <b>&quot;Chưa có tin — xem dự án&quot;</b> — CTA trỏ sang danh sách dự án (SC-04 là detail; entry dự án đi qua search/SC-02 filter &quot;dự án&quot;). Empty chỉ áp cho khối tin; khối phiên empty riêng: &quot;Chưa có phiên sắp mở — xem các phiên đã kết thúc → SC-05&quot;. <span class="ref">docs/05 §3</span></span></li><li><span class="num">9</span><span>Error từng khối độc lập: khối tin lỗi không kéo theo khối phiên. Hiện traceId rút gọn (8 ký tự đầu) để CS tra log; nút &quot;Thử lại&quot; chỉ refetch khối đó. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-01" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-01 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-01" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-01&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop 1440 (grid 3 cột) / tablet 768 (grid 2 cột) / mobile 360 (1 cột, nav vào menu ☰)</li><li>[ ] Đủ 4 trạng thái: Loading skeleton · Empty (&quot;Chưa có tin — xem dự án&quot;) · Error + traceId + Thử lại · Data</li><li>[ ] Card tin có đủ biến thể badge: ★ VIP / Đang bán (LISTED) / Sắp đấu giá (RESERVED) — màu badge theo enum docs/07 §3</li><li>[ ] Card phiên có biến thể LIVE (pulse đỏ) và SẮP MỞ (countdown + giờ đóng đăng ký GMT+7)</li><li>[ ] CTA &quot;Đăng bán&quot; vẽ đủ 3 nhánh đích: Guest→login-intent · KYC≠APPROVED→SC-21 · APPROVED→SC-22</li><li>[ ] Copy đúng docs/06 §5; tiền <code>1.250.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> + chú GMT+7</li><li>[ ] Không emoji icon trong UI production (🔍/🔴/🏢 trong wireframe là placeholder vị trí — thay bằng icon set thật)</li><li>[ ] Accessibility: contrast AA; ô search có label ẩn (aria); card là 1 link lớn nhưng tiêu đề vẫn là heading; focus ring cho nút</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd số tin hiển thị, thứ tự sort) cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const w=a(c,[["render",t]]);export{g as __pageData,w as default};
